diffs.patch:
Index: openwiki/.claims/architecture/configuration.json
===================================================================
--- openwiki/.claims/architecture/configuration.json	
+++ openwiki/.claims/architecture/configuration.json	
@@ -0,0 +1,114 @@
+{
+  "schemaVersion": 1,
+  "pageVersion": "sha256:5a00e5464a1d9914cb1915f1b7ff2ff67bd7e9029b1014b47789fc60b1367603",
+  "claims": [
+    {
+      "id": "claim_82b25b6ddfbe46d9b19fda15af2f0aba",
+      "statement": "step stores all per-user state beneath a single base path, defaulting to $HOME/.step and overridable with STEPPATH.",
+      "evidence": [
+        {
+          "resource": "repo://command/path/path.go#L10-L41",
+          "version": "repo-lines-v1:sha256:add1e9bd9095869fa6b42f1fcacca7b68d602e47e18749a7e11c03d79caf1707:"
+        }
+      ]
+    },
+    {
+      "id": "claim_70fb026e44f04fedb978af138763c6d5",
+      "statement": "When a current context is configured, step path resolves to <base>/authorities/<current-context> so each authority's configuration and trust material is isolated.",
+      "evidence": [
+        {
+          "resource": "repo://command/path/path.go#L24-L47",
+          "version": "repo-lines-v1:sha256:672bcf6d0050a8d25dbf37878c36735ece9b851b3537bbf6285240f50ac70e29:"
+        }
+      ]
+    },
+    {
+      "id": "claim_79bf495b0b6a4ec09e1a75391e72e444",
+      "statement": "Context metadata lives in contexts.json mapping context name to authority and profile, while the active context is recorded in current-context.json at the base path.",
+      "evidence": [
+        {
+          "resource": "repo://command/context/context.go#L14-L49",
+          "version": "repo-lines-v1:sha256:3caa3a7d672372d65373dc730e9e8c0f8c1135322c28a6c65abe4452598806b1:"
+        },
+        {
+          "resource": "repo://command/path/path.go#L40-L46",
+          "version": "repo-lines-v1:sha256:1446715ebb5e430e0f008d4fe3559d0a4cd5db44e19a651d715e4629e91d2eb0:"
+        }
+      ]
+    },
+    {
+      "id": "claim_23cdff92916a4b0b8c29359d7822a095",
+      "statement": "step context select persists the chosen authority context via step.Contexts().SaveCurrent.",
+      "evidence": [
+        {
+          "resource": "repo://command/context/select.go#L38-L43",
+          "version": "repo-lines-v1:sha256:71c48207e24e24f8cbe647da64cbb2d137d64221befaa38776fa6de2ffc1e22b:"
+        }
+      ]
+    },
+    {
+      "id": "claim_52b9acf6b04b4ef6aad67c55081e0513",
+      "statement": "step ca bootstrap downloads the root certificate to $STEPPATH/certs/root_ca.crt and writes config/defaults.json containing ca-url, fingerprint, root, and optionally redirect-url, provisioner, and min-password-length.",
+      "evidence": [
+        {
+          "resource": "repo://utils/cautils/bootstrap.go#L145-L221",
+          "version": "repo-lines-v1:sha256:4759bb4a1bbbf0c2501aad5c1d95631d72896a44f4da837e7379c1b1e38bcf70:"
+        }
+      ]
+    },
+    {
+      "id": "claim_fbc635fef6e349c4b3a887c3e26b2e57",
+      "statement": "After bootstrap, CA commands inherit --ca-url, --root and --fingerprint from defaults.json, so those flags need not be repeated.",
+      "evidence": [
+        {
+          "resource": "repo://utils/cautils/bootstrap.go#L25-L33",
+          "version": "repo-lines-v1:sha256:d7a50b3cb803f2ae5315e92e91ae8b201dc9cdadcd38e189386cead701f5b7f1:"
+        }
+      ]
+    },
+    {
+      "id": "claim_00e704d132d1426ba3246ca980863ff7",
+      "statement": "When the --root flag is empty, commands fall back to pki.GetRootCAPath() and report that --root is required if that default root file does not exist.",
+      "evidence": [
+        {
+          "resource": "repo://utils/cautils/client.go#L52-L74",
+          "version": "repo-lines-v1:sha256:728e02c9fda0397f940ca7b0af3633c0e94b12b6a90ea0c7f7b0dbc4d00b5619:"
+        }
+      ]
+    },
+    {
+      "id": "claim_cbf73c81a24040678ada82ea17b04592",
+      "statement": "ParseCaURL requires a non-empty value and enforces an https scheme, prepending https:// when absent; ParseCaURLIfExists allows an empty value.",
+      "evidence": [
+        {
+          "resource": "repo://flags/flags.go#L645-L669",
+          "version": "repo-lines-v1:sha256:ad89b5bf3b1119588f3dc5d16d64b279989eef7b3652069e5f2321b9a3436cf3:"
+        }
+      ]
+    },
+    {
+      "id": "claim_1df6f48da7f8433e92fba27d4d2dd8ad",
+      "statement": "step ca bootstrap can optionally install the downloaded root certificate into the system trust store using truststore.InstallFile.",
+      "evidence": [
+        {
+          "resource": "repo://utils/cautils/bootstrap.go#L212-L219",
+          "version": "repo-lines-v1:sha256:a5a81d2fc87277a3168775f5640a4ddaadc53d1cfcf809778b4c57f7f4a0e116:"
+        }
+      ]
+    },
+    {
+      "id": "claim_285ad2f9990048d791e096d54ebd744a",
+      "statement": "step ca init writes CA configuration under STEPPATH, registers a new context named after the first DNS name when contexts are enabled, and supports standalone, linked, hosted, CloudCAS, and StepCAS deployment types.",
+      "evidence": [
+        {
+          "resource": "repo://command/ca/init.go#L544-L570",
+          "version": "repo-lines-v1:sha256:5b3fcd12aa8a4b6a0ba5c59a536223c5954f3666895ac4c09e1ee49dd4fca318:"
+        }
+      ]
+    }
+  ],
+  "verification": {
+    "by": "openwiki/0.4.3",
+    "at": "2026-09-12T20:42:28.757Z"
+  }
+}

Index: openwiki/.claims/architecture/entrypoint.json
===================================================================
--- openwiki/.claims/architecture/entrypoint.json	
+++ openwiki/.claims/architecture/entrypoint.json	
@@ -0,0 +1,128 @@
+{
+  "schemaVersion": 1,
+  "pageVersion": "sha256:e3ddf7def6449352df96dc3e7f71ba1c80c5fad59d847375b4823d15e920e0d7",
+  "claims": [
+    {
+      "id": "claim_0c43ebb2179a4cee94453368cb27c4d0",
+      "statement": "cmd/step/main.go sets global identity strings and calls cmd.Run(); Run invokes run() which exits with an integer result.",
+      "evidence": [
+        {
+          "resource": "repo://cmd/step/main.go#L27-L28",
+          "version": "repo-lines-v1:sha256:c502637a51ae41bb7e17198196d4a89cfaaec674496555e0ca359d23b3885c32:"
+        },
+        {
+          "resource": "repo://internal/cmd/root.go#L46-L84",
+          "version": "repo-lines-v1:sha256:87243a7b5a79605440c5de01f0054b7a98dac7e59e665a7cdf51bae27ca786cb:"
+        }
+      ]
+    },
+    {
+      "id": "claim_69c7380a41484860b4d9a185ade761e9",
+      "statement": "run() first calls step.Init() to set up the step environment, then builds the urfave/cli app and runs it; any app error yields exit code 1 and empty success yields 0.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cmd/root.go#L50-L84",
+          "version": "repo-lines-v1:sha256:47571aeb137a4981e5c055373f0388c8342599d4ba3d78ae32f9e91c1f8d173f:"
+        }
+      ]
+    },
+    {
+      "id": "claim_53a7cd9b9642450bb73d66b90a459880",
+      "statement": "Commands are registered by blank-importing top-level command packages whose init() calls command.Register, and app.Commands = command.Retrieve() assembles the command tree.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cmd/root.go#L122-L122",
+          "version": "repo-lines-v1:sha256:36102ae7bba57ca990a4cd767c425a0a69adc07aa207ece02fca85121bee91ae:"
+        },
+        {
+          "resource": "repo://internal/cmd/root.go#L26-L44",
+          "version": "repo-lines-v1:sha256:4231ec5f5747d03bf1a07b8d8e091ac2a4773a32e36d7f0edd17e2570526142e:"
+        }
+      ]
+    },
+    {
+      "id": "claim_91330754109441c98d1bd6aa4a5b71c2",
+      "statement": "When a first argument is not a built-in command, app.Action looks up and runs a step-<name>-plugin executable, falling back to command help or app help.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cmd/root.go#L134-L146",
+          "version": "repo-lines-v1:sha256:8d64ccb7d992ddddac9d329ea7dd12960ab99537908cb116a420528d10eabc92:"
+        }
+      ]
+    },
+    {
+      "id": "claim_0a7eef2c7356458ebe04cc218a7850e4",
+      "statement": "Errors are printed to stderr; with STEPDEBUG=1 the full error stack is shown, otherwise a message and a suggestion to re-run with STEPDEBUG=1.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cmd/root.go#L62-L82",
+          "version": "repo-lines-v1:sha256:212a7a9767328a715b770ee0fd24ba4093cb46c18a3d742bb12958f821336734:"
+        }
+      ]
+    },
+    {
+      "id": "claim_72fcefde2b28429893f736339207af52",
+      "statement": "The deferred panicHandler exits with code 2 on a recovered panic unless STEPDEBUG=1, in which case it re-raises the panic.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cmd/root.go#L156-L170",
+          "version": "repo-lines-v1:sha256:5d37a92a8688f96bf908d753c092322a909e0eace194f9f0b132dc126cd3b271:"
+        }
+      ]
+    },
+    {
+      "id": "claim_f03042b256bb466bb1a96ec9206169b1",
+      "statement": "step.Init() failure writes the error to stderr and returns exit code 1.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cmd/root.go#L54-L57",
+          "version": "repo-lines-v1:sha256:61699eecd588ee398701f290c28de40d9c2ce9859a92bf3c859db1effbe08860:"
+        }
+      ]
+    },
+    {
+      "id": "claim_71a3cfcb1e1c4d8981bc3685c1fa7aa8",
+      "statement": "plugin.LookPath searches $STEPPATH/plugins and PATH for step-<name>-plugin, handling Windows extensions.",
+      "evidence": [
+        {
+          "resource": "repo://internal/plugin/plugin.go#L15-L52",
+          "version": "repo-lines-v1:sha256:b32f49ff09846f3cbdb3c78b7cb96872e0de6c54c515e7e321f35137525eb50a:"
+        }
+      ]
+    },
+    {
+      "id": "claim_abb31f00a8c34a1da07e19d26bbab53c",
+      "statement": "step completion prints embedded bash and zsh scripts and a urfave/cli-generated fish completion script.",
+      "evidence": [
+        {
+          "resource": "repo://command/completion/completion.go#L100-L123",
+          "version": "repo-lines-v1:sha256:9258fbff8838b020b7aaa70d2d7710b0c092efe52e1fb3db409cc0942ff720cf:"
+        }
+      ]
+    },
+    {
+      "id": "claim_ecee44a987344858bd331c2f7994fe68",
+      "statement": "utils.Fail prints the error (full stack under STEPDEBUG) and exits 1.",
+      "evidence": [
+        {
+          "resource": "repo://utils/utils.go#L12-L23",
+          "version": "repo-lines-v1:sha256:fea5d4fef76bc5a239fd5500dfd7e82f71fd33b78e7372012857ef0fe687cd36:"
+        }
+      ]
+    },
+    {
+      "id": "claim_632646851c4f40689e511c93e92906b5",
+      "statement": "root_test.go asserts newApp assembles the expected top-level command set: help, api, base64, fileserver, path, certificate, completion, context, crl, crypto, oauth, version, ca, beta, ssh.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cmd/root_test.go#L18-L36",
+          "version": "repo-lines-v1:sha256:5b22b3448bb978be593409d56004f8265d9dc9e9c8e8e21d15eae1b5b01b1567:"
+        }
+      ]
+    }
+  ],
+  "verification": {
+    "by": "openwiki/0.4.3",
+    "at": "2026-09-12T20:42:28.757Z"
+  }
+}

