Index: openwiki/.claims/extensions/plugins.json
===================================================================
--- openwiki/.claims/extensions/plugins.json	
+++ openwiki/.claims/extensions/plugins.json	
@@ -0,0 +1,90 @@
+{
+  "schemaVersion": 1,
+  "pageVersion": "sha256:9003720a5a0f7d200082f655925f63abc34f34241a16e922d5d0d06d20fe0130",
+  "claims": [
+    {
+      "id": "claim_3ec6e0ce763247cfb2d46226a968b464",
+      "statement": "step discovers plugins as executables named step-<name>-plugin, searched first in $STEPPATH/plugins and then in PATH.",
+      "evidence": [
+        {
+          "resource": "repo://internal/plugin/plugin.go#L15-L52",
+          "version": "repo-lines-v1:sha256:b32f49ff09846f3cbdb3c78b7cb96872e0de6c54c515e7e321f35137525eb50a:"
+        }
+      ]
+    },
+    {
+      "id": "claim_e751770e745546bf98c545a5d5cbeba9",
+      "statement": "On Windows, plugin resolution checks .com/.exe/.bat/.cmd/.ps1 extensions in $STEPPATH/plugins first, then PATH, honoring PATHEXT.",
+      "evidence": [
+        {
+          "resource": "repo://internal/plugin/plugin.go#L21-L44",
+          "version": "repo-lines-v1:sha256:3feeaa0ced712fc270f4a1de5a7751d72468e65242ad0f7de6544ee6fd522ec6:"
+        }
+      ]
+    },
+    {
+      "id": "claim_dbee4fe0f80c42ef919e23e60c076ce7",
+      "statement": "plugin.Run executes the plugin forwarding stdin/stdout/stderr, and on Windows invokes .ps1 plugins through PowerShell.",
+      "evidence": [
+        {
+          "resource": "repo://internal/plugin/plugin.go#L56-L72",
+          "version": "repo-lines-v1:sha256:955a40c4b1c955b57423bfe4de33df2b9fa255ce31d3ab9ba3acb8fdd8515bff:"
+        }
+      ]
+    },
+    {
+      "id": "claim_d467b2ea52474322a37a5e8e879f1ccc",
+      "statement": "When the first argument is not a built-in command, app.Action resolves and runs the step-<name>-plugin, and points users to a download URL for known plugins.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cmd/root.go#L134-L146",
+          "version": "repo-lines-v1:sha256:8d64ccb7d992ddddac9d329ea7dd12960ab99537908cb116a420528d10eabc92:"
+        }
+      ]
+    },
+    {
+      "id": "claim_fa18e57ec85e402c85d41342dcfbfb20",
+      "statement": "internal/cryptoutil integrates the step-kms-plugin so keys referenced by KMS URIs or KMS-style names can sign certificates and tokens, backed by hardware or cloud KMS.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cryptoutil/cryptoutil.go#L14-L45",
+          "version": "repo-lines-v1:sha256:3e152cc77ed776a9910be83abd855e447f3f031274b71639e4f09f87cd6d7ba2:"
+        }
+      ]
+    },
+    {
+      "id": "claim_91827959f9e2446da68811c4d7d8eabd",
+      "statement": "The supported KMS URI types include YubiKey PIV, PKCS #11, TPM 2.0, Google Cloud KMS, AWS KMS, and Azure Key Vault, per flags.KMSUri.",
+      "evidence": [
+        {
+          "resource": "repo://flags/flags.go#L471-L508",
+          "version": "repo-lines-v1:sha256:fbdc745ba2c798aed8ac6035761f577329c3a08d83e8b50f2ff5e1e5ebf10a06:"
+        }
+      ]
+    },
+    {
+      "id": "claim_ea0a7a4ea08d4921bbdad492c7fed735",
+      "statement": "plugin.GetURL returns a download URL for the known 'kms' plugin pointing to the step-kms-plugin repository.",
+      "evidence": [
+        {
+          "resource": "repo://internal/plugin/plugin.go#L74-L82",
+          "version": "repo-lines-v1:sha256:e343acce7ca6f58483aa97b627b886e14ebcaaaf46a5fd6387e6d7370b78739b:"
+        }
+      ]
+    },
+    {
+      "id": "claim_d5f4327c3895402e8566792cf7607d74",
+      "statement": "The README documents the plugin naming convention step-<name>-plugin, the $PATH and $STEPPATH/plugins search paths, and lists kms and kmsproxy as known plugins.",
+      "evidence": [
